// ------------------------------------------------------------------
// Íconos de Convive (Iconography del Figma). Línea y relleno, 24×24.
// Se usan como cualquier ImageVector: Icon(Ic.Home, contentDescription = null)
// ------------------------------------------------------------------

object Ic {
    private fun icon(name: String, vararg paths: Pair<String, Boolean>): ImageVector {
        val b = ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
        paths.forEach { (d, evenOdd) ->
            b.addPath(
                pathData = PathParser().parsePathString(d).toNodes(),
                pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(Color.Black)
            )
        }
        return b.build()
    }

